    {
      id: 29,
      title: "Unit 29",
      storyTitle: "How the World Got Light",
      story: "The president of Darkland was a pig—a very bad pig. He was a pig of major importance. He was rich, and he had a lot of strength. But he was mean to all the animals in Darkland. He kept all of the world’s light in a bag. He preferred to keep the world cool and dark. He wanted to stop the progress of the city. The animals couldn’t work in the dark. He didn’t have any respect for them. “Light is too good for them,” he said. “Only I should have light.”\n\nBut the animals needed light. So they decided to hold a competition. They wanted to find the smartest animal in Darkland. That animal had to steal light from the president. They advertised the competition everywhere. All the animals came. The animals all showed off their skills. The audience watched and then voted for the animal with the most knowledge. The winner was a tall bird named Raven. They assigned him the job of getting light.\n\nThe next morning, Raven ate breakfast and then left his home. “How will I gain light from the president?” thought Raven. He needed to trick the president somehow. Then, Raven had an idea. Raven could make his voice sound like anything!\n\nRaven walked up to the president’s door. He made the sound of a crying baby. He cried very loudly. Soon, the president opened the door.\n\n“Be quiet!” the president yelled. Right then, Raven quickly made his move. He flew by the pig and found the soft bag. He took it outside. The sun was inside the bag. Raven flew high and put the sun in the sky. The president was very mad, but Raven and the animals were very happy. At last, they had light—all thanks to clever thinking.",
      words: [
        { id: "29-1", word: "advertise", ipa: "/ˈædvərtaɪz/", pos: "v.", definition: "To advertise is to tell people about something on TV, radio, etc.", example: "They used a rabbit to help them advertise their product.", examples: ["They advertise their shoes on TV.", "The shop advertised a big sale."], vi: "quảng cáo", forms: ["advertised", "advertise"] },
        { id: "29-2", word: "assign", ipa: "/əˈsaɪn/", pos: "v.", definition: "To assign something to someone is to tell them to do it.", example: "I assigned the worker an important task.", examples: ["The teacher assigned homework to the class.", "She was assigned to a new project."], vi: "giao, phân công", forms: ["assigned", "assign"] },
        { id: "29-3", word: "audience", ipa: "/ˈɔːdiəns/", pos: "n.", definition: "An audience is a group of people who watch something together.", example: "There was a large audience at the game.", examples: ["The audience clapped loudly.", "The theater holds an audience of 500."], vi: "khán giả", forms: ["audience"] },
        { id: "29-4", word: "breakfast", ipa: "/ˈbrekfəst/", pos: "n.", definition: "Breakfast is the first meal of the day.", example: "I eat breakfast at 8:00 every morning.", examples: ["I eat eggs for breakfast.", "Breakfast is ready."], vi: "bữa sáng", forms: ["breakfast"] },
        { id: "29-5", word: "competition", ipa: "/ˌkɑːmpəˈtɪʃn/", pos: "n.", definition: "A competition is a contest to see who is the best at something.", example: "He won the running competition over the weekend.", examples: ["She won first place in the competition.", "There is strong competition between the two shops."], vi: "cuộc thi, sự cạnh tranh", forms: ["competition"] },
        { id: "29-6", word: "cool", ipa: "/kuːl/", pos: "adj.", definition: "If the weather is cool, it is a little bit cold.", example: "The weather is cool in the fall.", examples: ["It is cool in the shade.", "That’s a cool bike!"], vi: "mát mẻ, ngầu", forms: ["cool"] },
        { id: "29-7", word: "gain", ipa: "/ɡeɪn/", pos: "v.", definition: "Ifyou gain something, you get more of it.", example: "I gained some weight over the summer.", examples: ["He gained weight during the holidays.", "You can gain experience by working hard."], vi: "đạt được, tăng thêm", forms: ["gained", "gain"] },
        { id: "29-8", word: "importance", ipa: "/ɪmˈpɔːrtns/", pos: "n.", definition: "Importance means the quality or condition of being needed or valued.", example: "VIPs are people of great importance.", examples: ["Teachers know the importance of reading.", "The importance of sleep is clear."], vi: "tầm quan trọng", forms: ["importance"] },
        { id: "29-9", word: "knowledge", ipa: "/ˈnɑːlɪdʒ/", pos: "n.", definition: "Knowledge is information that you have about something.", example: "A music teacher should have good knowledge of music.", examples: ["Reading gives you knowledge.", "He has a good knowledge of history."], vi: "kiến thức", forms: ["knowledge"] },
        { id: "29-10", word: "major", ipa: "/ˈmeɪdʒər/", pos: "adj.", definition: "If something is major, it is big or important.", example: "I have a major problem. My boss wants me to redo my project!", examples: ["Traffic is a major problem in big cities.", "She made a major discovery."], vi: "chính, quan trọng", forms: ["major"] },
        { id: "29-11", word: "mean", ipa: "/miːn/", pos: "adj.", definition: "Mean describes someone who is unkind or cruel.", example: "My co-worker is a very mean person. He gets angry very quickly.", examples: ["Don’t be mean to your sister.", "The mean boy took my toy."], vi: "xấu tính, ác ý", forms: ["mean"] },
        { id: "29-12", word: "prefer", ipa: "/prɪˈfɜːr/", pos: "v.", definition: "Ifyou prefer something, you want it more than something else.", example: "I prefer to take the path that will lead me to a bright future.", examples: ["I prefer tea to coffee.", "She prefers to walk to work."], vi: "thích hơn", forms: ["preferred", "prefers", "prefer"] },
        { id: "29-13", word: "president", ipa: "/ˈprezɪdənt/", pos: "n.", definition: "A president is the leader of a country.", example: "The president of our country made an important announcement.", examples: ["The president gave a speech on TV.", "He is the president of the school club."], vi: "tổng thống, chủ tịch", forms: ["president"] },
        { id: "29-14", word: "progress", ipa: "/ˈprɑːɡres/", pos: "n.", definition: "Progress is the act of getting closer to doing or finishing something.", example: "Our company made financial progress this year.", examples: ["She is making good progress in English.", "The progress of the project is slow."], vi: "sự tiến bộ", forms: ["progress"] },
        { id: "29-15", word: "respect", ipa: "/rɪˈspekt/", pos: "n.", definition: "Respect is a good opinion of someone because they are good.", example: "I have great respect for firemen.", examples: ["Children should show respect to their elders.", "I have great respect for my teacher."], vi: "sự tôn trọng", forms: ["respect"] },
        { id: "29-16", word: "rich", ipa: "/rɪtʃ/", pos: "adj.", definition: "Ifyou are rich, you have a lot of money.", example: "He’s rich. He can buy anything he wants.", examples: ["He became rich by selling computers.", "The soup is rich and creamy."], vi: "giàu có", forms: ["rich"] },
        { id: "29-17", word: "skill", ipa: "/skɪl/", pos: "n.", definition: "A skill is the knowledge and ability that allows you to do something well.", example: "A snowboarder must have the right skills to do well.", examples: ["Cooking is a useful skill.", "She has great skill in drawing."], vi: "kỹ năng", forms: ["skills", "skill"] },
        { id: "29-18", word: "somehow", ipa: "/ˈsʌmhaʊ/", pos: "adv.", definition: "Somehow means in a way or by some means which is not known.", example: "He somehow had to find a way to reach the life preserver.", examples: ["We will solve the problem somehow.", "Somehow, he found his way home."], vi: "bằng cách nào đó", forms: ["somehow"] },
        { id: "29-19", word: "strength", ipa: "/streŋθ/", pos: "n.", definition: "Strength is the physical power that you have.", example: "Exercising will increase your strength and give you more power.", examples: ["He lifted the box with great strength.", "Honesty is her greatest strength."], vi: "sức mạnh", forms: ["strength"] },
        { id: "29-20", word: "vote", ipa: "/voʊt/", pos: "v.", definition: "To vote is to officially choose between two or more things.", example: "I voted for Billy to be our class president.", examples: ["Citizens vote in the election every four years.", "We voted for a new class leader."], vi: "bỏ phiếu", forms: ["voted", "vote"] }
      ]
    },
    /* ======================================================================
       UNIT 30
       ====================================================================== */
    {
      id: 30,
      title: "Unit 30",
      storyTitle: "Cats and Secrets",
      story: "In English, there is a common idiom “let the cat out of the bag.” It means to tell a secret. But where did this idiom start?\n\nIt came from a section of England. Long ago, people there went from town to town to sell things like vegetables, clothes, and pigs. They had strong beliefs about honesty. They didn’t like lying. One day, a man went to the section’s center to sell things.\n\n“I have a baby pig for sale! It won’t cost much,” he said. He held the animal above his head. His style was different from honest people’s style. He was a master of tricking people and lying.\n\nA woman named Beth scanned his pig. He offered her the pig for one gold coin. That was a very small amount. Beth gave him the coin. He put it in his pocket. He walked ahead of Beth to get the pig.\n\nHe gave her a closed bag and said, “Here’s your pig.” He then left very quickly.\n\nBeth looked at the bag’s surface. It was moving. She opened it to let the pig out. A cat was inside! “He tricked me! That isn’t proper,” she said.\n\nLater, the man returned to trick more people. Beth saw him and the memory of the cat came back. She told her friends. They stopped him. But no one knew what to do next.\n\nSomeone said, “We need an independent and fair person to decide that.” They went to the judge. Beth told him about the cat in the bag.\n\nThe judge asked, “Is there evidence? Can you demonstrate how he did it?”\n\n“Look in his bag,” said Beth. She opened it and let a cat out of the bag. They learned the man’s secret, and he went to jail.\n\nThat’s how the idiom “let the cat out of the bag” came to mean to tell a secret.",
      words: [
        { id: "30-1", word: "above", ipa: "/əˈbʌv/", pos: "prep.", definition: "If something is above, it is at a higher level than something else.", example: "He straightened the sign that was above the crowd.", examples: ["The plane flew above the clouds.", "There is a picture above the fireplace."], vi: "phía trên", forms: ["above"] },
        { id: "30-2", word: "ahead", ipa: "/əˈhed/", pos: "adv.", definition: "If something is ahead of something else, it is in front of it.", example: "The blue car drove on ahead of us.", examples: ["Go straight ahead.", "He ran ahead of the others."], vi: "phía trước", forms: ["ahead"] },
        { id: "30-3", word: "amount", ipa: "/əˈmaʊnt/", pos: "n.", definition: "An amount is how much there is of something.", example: "Can I use my card to pay for the entire amount?", examples: ["A large amount of money was lost.", "Add a small amount of salt."], vi: "số lượng", forms: ["amount"] },
        { id: "30-4", word: "belief", ipa: "/bɪˈliːf/", pos: "n.", definition: "A belief is a strong feeling that something is correct or true.", example: "A preacher or priest should have a strong belief in God.", examples: ["He has a strong belief in God.", "It is my belief that everyone can learn."], vi: "niềm tin", forms: ["beliefs", "belief"] },
        { id: "30-5", word: "center", ipa: "/ˈsentər/", pos: "n.", definition: "The center of something is the middle of it.", example: "The center of a dart board is the most important spot.", examples: ["The library is in the center of town.", "She stood in the center of the room."], vi: "trung tâm", forms: ["center"] },
        { id: "30-6", word: "common", ipa: "/ˈkɑːmən/", pos: "adj.", definition: "If something is common, it happens often or there is much of it.", example: "It is common for snow to fall in the winter.", examples: ["“Smith” is a common name.", "It is common to see deer here."], vi: "phổ biến", forms: ["common"] },
        { id: "30-7", word: "cost", ipa: "/kɔːst/", pos: "v.", definition: "To cost is to require expenditure or payment.", example: "These designer shoes cost more than the regular ones.", examples: ["This bag costs ten dollars.", "The repair cost a lot of money."], vi: "có giá, tốn", forms: ["costs", "cost"] },
        { id: "30-8", word: "demonstrate", ipa: "/ˈdemənstreɪt/", pos: "v.", definition: "To demonstrate something is to show how it is done.", example: "She demonstrated her plan to her co-workers.", examples: ["The teacher demonstrated how to use the machine.", "The test demonstrates his skill."], vi: "chứng minh, trình diễn", forms: ["demonstrated", "demonstrates", "demonstrate"] },
        { id: "30-9", word: "different", ipa: "/ˈdɪfrənt/", pos: "adj.", definition: "Different describes someone or something that is not the same as others.", example: "Each of my sisters has a different hair style from one another.", examples: ["My brother and I are very different.", "This book is different from that one."], vi: "khác nhau", forms: ["different"] },
        { id: "30-10", word: "evidence", ipa: "/ˈevɪdəns/", pos: "n.", definition: "Evidence is a fact or thing that you use to prove something.", example: "He used the pictures as evidence that UFOs are real.", examples: ["The police found no evidence.", "There is clear evidence that the earth is round."], vi: "bằng chứng", forms: ["evidence"] },
        { id: "30-11", word: "honesty", ipa: "/ˈɑːnəsti/", pos: "n.", definition: "Honesty means the quality of being truthful or honest.", example: "A courtroom should be a place of honesty.", examples: ["Honesty is the best policy.", "His honesty made everyone trust him."], vi: "sự trung thực", forms: ["honesty"] },
        { id: "30-12", word: "idiom", ipa: "/ˈɪdiəm/", pos: "n.", definition: "An idiom is a phrase with a meaning different from its words.", example: "The idiom “when pigs fly” means that something will never happen.", examples: ["“Piece of cake” is an English idiom.", "She is learning idioms to speak more naturally."], vi: "thành ngữ", forms: ["idioms", "idiom"] },
        { id: "30-13", word: "independent", ipa: "/ˌɪndɪˈpendənt/", pos: "adj.", definition: "If something is independent, it is not controlled by something else.", example: "She chose to live an independent life in the country.", examples: ["She is an independent young woman.", "The country became independent in 1945."], vi: "độc lập", forms: ["independent"] },
        { id: "30-14", word: "inside", ipa: "/ɪnˈsaɪd/", pos: "n.", definition: "Inside means the inner part, space or side of something.", example: "The inside of the box was empty.", examples: ["The inside of the house was warm.", "The inside of the apple was brown."], vi: "bên trong, phần trong", forms: ["inside"] },
        { id: "30-15", word: "master", ipa: "/ˈmæstər/", pos: "n.", definition: "A master is a person who is very good at something.", example: "My brother is a master of taekwondo.", examples: ["He is a master of the guitar.", "The dog waited for its master."], vi: "bậc thầy, chủ nhân", forms: ["master"] },
        { id: "30-16", word: "memory", ipa: "/ˈmeməri/", pos: "n.", definition: "A memory is something you remember.", example: "The memory of my first time in the city will always be the best.", examples: ["She has a good memory for faces.", "That trip is a happy memory for me."], vi: "trí nhớ, kỷ niệm", forms: ["memory"] },
        { id: "30-17", word: "proper", ipa: "/ˈprɑːpər/", pos: "adj.", definition: "If something is proper, it is right.", example: "It is not proper to throw your garbage on the road.", examples: ["Use the proper tool for the job.", "He doesn’t have proper shoes for hiking."], vi: "đúng đắn, thích hợp", forms: ["proper"] },
        { id: "30-18", word: "scan", ipa: "/skæn/", pos: "v.", definition: "To scan something is to look at it very carefully.", example: "You must scan each person closely.", examples: ["I scanned the page for his name.", "The machine scans the bags at the airport."], vi: "quét, đọc lướt", forms: ["scanned", "scans", "scan"] },
        { id: "30-19", word: "section", ipa: "/ˈsekʃn/", pos: "n.", definition: "A section is a part of something larger.", example: "The green section of the graph is the most important part.", examples: ["Read the first section of the book.", "The children’s section is on the second floor."], vi: "phần, khu vực", forms: ["section"] },
        { id: "30-20", word: "surface", ipa: "/ˈsɜːrfɪs/", pos: "n.", definition: "The surface of something is the top part or outside of it.", example: "The surface of the moon is very rough.", examples: ["The surface of the lake was calm.", "Clean the surface of the table."], vi: "bề mặt", forms: ["surface"] }
      ]
    }
